<?php
require_once __DIR__.'/../includes/init.php';require_admin();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=(string)($_POST['action']??'');try{if($action==='add'){get_or_create_skill(trim((string)($_POST['skill_name']??'')),trim((string)($_POST['category']??'General')));flash('success','Skill added.');}elseif($action==='delete'){$id=(int)($_POST['id']??0);db()->prepare('DELETE FROM skills WHERE id=?')->execute([$id]);flash('success','Skill deleted.');}}catch(Throwable $e){flash('danger',$e->getMessage());}redirect('admin/skills.php');}
$stmt=db()->query("SELECT s.*,(SELECT COUNT(*) FROM user_skills us WHERE us.skill_id=s.id) user_count FROM skills s ORDER BY s.category,s.skill_name");$skills=$stmt->fetchAll();$pageTitle='Admin Skills - Campus Connect';include __DIR__.'/_admin_header.php';
?>
<div class="admin-title"><div><h1>Skills</h1><p>Maintain the shared platform skill library.</p></div></div><section class="admin-panel"><form class="admin-add-form" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="add"><input name="skill_name" placeholder="Skill name" required maxlength="120"><input name="category" placeholder="Category" maxlength="120"><button>Add Skill</button></form></section><section class="admin-panel table-wrap"><table class="admin-table"><thead><tr><th>Skill</th><th>Category</th><th>Used by</th><th>Action</th></tr></thead><tbody><?php foreach($skills as $skill): ?><tr><td><strong><?= e($skill['skill_name']) ?></strong></td><td><?= e($skill['category']) ?></td><td><?= (int)$skill['user_count'] ?> users</td><td><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= (int)$skill['id'] ?>"><button class="danger" data-confirm="Delete this skill? It will be removed from user profiles.">Delete</button></form></td></tr><?php endforeach; ?></tbody></table></section>
<?php include __DIR__.'/_admin_footer.php'; ?>
